// Authored NOT_RUN, ranges fixture only covers ASCII and one supplementary point.
use kni_core::os2_consistency::{required_ranges,UnicodeRangeSpan};
#[test]fn ranges_explicit(){let spans=[UnicodeRangeSpan{first:0,last:127,bit:0},UnicodeRangeSpan{first:0x1f600,last:0x1f600,bit:57}];assert_eq!(required_ranges(&[(65,1)],&spans).unwrap(),[1,0,0,0]);assert_eq!(required_ranges(&[(0x1f600,1)],&spans).unwrap(),[0,1<<25,0,0]);assert!(required_ranges(&[(0x400,1)],&spans).is_err());assert!(required_ranges(&[(0xd800,1)],&spans).is_err());}
use kni_core::os2_consistency::verify;
use kni_core::sfnt_metadata::Os2Metadata;
fn metadata()->Os2Metadata{Os2Metadata{average_width:500,weight:400,width:5,embedding:2,subscript:[650,600,0,75],superscript:[650,600,0,350],strikeout:[50,300],family_class:0,panose:[0;10],unicode_ranges:[1,0,0,0],vendor:*b"TEST",selection:64,first_char:65,last_char:65,typo:[800,-200,0],win_ascent:800,win_descent:200, version: 0, cap_height: 0, x_height: 0 }}
#[test]fn average_masks_and_clipping(){let m=metadata();assert!(verify(&m,&[(65,1)],&[500,500],[1,0,0,0],500,[0,100],true).is_ok());assert!(verify(&m,&[(65,1)],&[500,500],[2,0,0,0],500,[0,100],true).is_err());assert!(verify(&m,&[(65,1)],&[500,502],[1,0,0,0],500,[0,100],true).is_err());assert!(verify(&m,&[(65,1)],&[500,500],[1,0,0,0],500,[0,900],true).is_err());assert!(verify(&m,&[(65,1)],&[500,500],[1,0,0,0],500,[0,900],false).is_ok());}
#[test]fn explicit_rounding_floor_or_ceil_only(){let mut m=metadata();for selected in [500,501]{m.average_width=selected;assert!(verify(&m,&[(65,1)],&[500,501],[1,0,0,0],selected,[0,100],true).is_ok());}m.average_width=499;assert!(verify(&m,&[(65,1)],&[500,501],[1,0,0,0],499,[0,100],true).is_err());}
#[test]fn designer_can_decline_range_functionality(){let mut m=metadata();m.unicode_ranges=[0;4];assert!(verify(&m,&[(65,1)],&[500,500],[1,0,0,0],500,[0,100],true).is_ok());}
#[test]fn published_ranges(){use kni_core::os2_ranges::ASSIGNED_SPANS;assert_eq!(ASSIGNED_SPANS.len(),169);assert_eq!(required_ranges(&[(65,1)],ASSIGNED_SPANS).unwrap(),[1,0,0,0]);let mask=required_ranges(&[(0x10900,1)],ASSIGNED_SPANS).unwrap();assert_eq!(mask[1],(1<<25)|(1<<26));let mask=required_ranges(&[(0x20000,1)],ASSIGNED_SPANS).unwrap();assert_eq!(mask[1],(1<<25)|(1<<27));}
